-- changeset guardfind:1
-- comment 天下无拐一期业务表：C 端账号、寻人档案、线索、消息、治理、采集
-- ----------------------------
-- C 端账号
-- ----------------------------
CREATE TABLE IF NOT EXISTS "gf_app_user" (
    "id"                   int8 GENERATED BY DEFAULT AS IDENTITY,
    "nickname"             varchar(30) NOT NULL,
    "avatar"               varchar(500) DEFAULT NULL,
    "gender"               int2 NOT NULL DEFAULT 0,
    "phone"                varchar(255) DEFAULT NULL,
    "password"             varchar(255) DEFAULT NULL,
    "account_status"       int2 NOT NULL DEFAULT 1,
    "identity_type"        varchar(16) NOT NULL DEFAULT 'PUBLIC',
    "real_name_status"     varchar(16) NOT NULL DEFAULT 'UNCHECKED',
    "province_code"        varchar(12) DEFAULT NULL,
    "city_code"            varchar(12) DEFAULT NULL,
    "district_code"        varchar(12) DEFAULT NULL,
    "volunteer_verified"   bool NOT NULL DEFAULT false,
    "registration_source"  varchar(16) NOT NULL DEFAULT 'APP',
    "last_active_time"     timestamp DEFAULT NULL,
    "deactivate_apply_time" timestamp DEFAULT NULL,
    "create_user"          int8 DEFAULT NULL,
    "create_time"          timestamp NOT NULL,
    "update_user"          int8 DEFAULT NULL,
    "update_time"          timestamp DEFAULT NULL,
    "deleted"              int8 NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "gf_app_user_uk_phone" ON "gf_app_user" ("phone", "deleted");
CREATE INDEX IF NOT EXISTS "gf_app_user_idx_account_status" ON "gf_app_user" ("account_status");
CREATE INDEX IF NOT EXISTS "gf_app_user_idx_create_time" ON "gf_app_user" ("create_time");
CREATE INDEX IF NOT EXISTS "gf_app_user_idx_deleted" ON "gf_app_user" ("deleted");
COMMENT ON COLUMN "gf_app_user"."id" IS 'ID';
COMMENT ON COLUMN "gf_app_user"."nickname" IS '昵称';
COMMENT ON COLUMN "gf_app_user"."avatar" IS '头像地址';
COMMENT ON COLUMN "gf_app_user"."gender" IS '性别（0：未知；1：男；2：女）';
COMMENT ON COLUMN "gf_app_user"."phone" IS '手机号码（加密存储）';
COMMENT ON COLUMN "gf_app_user"."password" IS '密码（BCRYPT）';
COMMENT ON COLUMN "gf_app_user"."account_status" IS '账号状态（1：正常；2：锁定；3：注销申请中；4：已注销）';
COMMENT ON COLUMN "gf_app_user"."identity_type" IS '身份类型（GUARDIAN：家属；VOLUNTEER：志愿者；PUBLIC：普通用户）';
COMMENT ON COLUMN "gf_app_user"."real_name_status" IS '实名状态（UNCHECKED/CHECKING/PASSED/REJECTED）';
COMMENT ON COLUMN "gf_app_user"."province_code" IS '常驻省编码';
COMMENT ON COLUMN "gf_app_user"."city_code" IS '常驻市编码';
COMMENT ON COLUMN "gf_app_user"."district_code" IS '常驻区县编码';
COMMENT ON COLUMN "gf_app_user"."volunteer_verified" IS '志愿者是否已认证';
COMMENT ON COLUMN "gf_app_user"."registration_source" IS '注册来源（APP/COLLECT_IMPORT）';
COMMENT ON COLUMN "gf_app_user"."last_active_time" IS '最后活跃时间';
COMMENT ON COLUMN "gf_app_user"."deactivate_apply_time" IS '注销申请时间（冷静期起点）';
COMMENT ON COLUMN "gf_app_user"."create_user" IS '创建人';
COMMENT ON COLUMN "gf_app_user"."create_time" IS '创建时间';
COMMENT ON COLUMN "gf_app_user"."update_user" IS '修改人';
COMMENT ON COLUMN "gf_app_user"."update_time" IS '修改时间';
COMMENT ON COLUMN "gf_app_user"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON TABLE "gf_app_user" IS 'App 用户表';

CREATE TABLE IF NOT EXISTS "gf_app_device" (
    "id"           int8 GENERATED BY DEFAULT AS IDENTITY,
    "user_id"      int8 NOT NULL,
    "platform"     varchar(16) NOT NULL,
    "device_id"    varchar(128) NOT NULL,
    "device_name"  varchar(64) DEFAULT NULL,
    "push_token"   varchar(512) DEFAULT NULL,
    "app_version"  varchar(32) DEFAULT NULL,
    "os_version"   varchar(32) DEFAULT NULL,
    "last_login_time" timestamp DEFAULT NULL,
    "create_user"  int8 DEFAULT NULL,
    "create_time"  timestamp NOT NULL,
    "update_user"  int8 DEFAULT NULL,
    "update_time"  timestamp DEFAULT NULL,
    "deleted"      int8 NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "gf_app_device_uk_user_device" ON "gf_app_device" ("user_id", "device_id", "deleted");
CREATE INDEX IF NOT EXISTS "gf_app_device_idx_user_id" ON "gf_app_device" ("user_id");
CREATE INDEX IF NOT EXISTS "gf_app_device_idx_deleted" ON "gf_app_device" ("deleted");
COMMENT ON COLUMN "gf_app_device"."id" IS 'ID';
COMMENT ON COLUMN "gf_app_device"."user_id" IS 'App 用户 ID';
COMMENT ON COLUMN "gf_app_device"."platform" IS '平台（IOS/ANDROID/HARMONY/WEB）';
COMMENT ON COLUMN "gf_app_device"."device_id" IS '设备标识';
COMMENT ON COLUMN "gf_app_device"."device_name" IS '设备名称';
COMMENT ON COLUMN "gf_app_device"."push_token" IS '厂商推送 token（一期不写入，二期启用）';
COMMENT ON COLUMN "gf_app_device"."app_version" IS 'App 版本';
COMMENT ON COLUMN "gf_app_device"."os_version" IS '系统版本';
COMMENT ON COLUMN "gf_app_device"."last_login_time" IS '最后登录时间';
COMMENT ON COLUMN "gf_app_device"."create_user" IS '创建人';
COMMENT ON COLUMN "gf_app_device"."create_time" IS '创建时间';
COMMENT ON COLUMN "gf_app_device"."update_user" IS '修改人';
COMMENT ON COLUMN "gf_app_device"."update_time" IS '修改时间';
COMMENT ON COLUMN "gf_app_device"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON TABLE "gf_app_device" IS 'App 设备表';

-- ----------------------------
-- 寻人档案
-- ----------------------------
CREATE TABLE IF NOT EXISTS "gf_find_case" (
    "id"                  int8 GENERATED BY DEFAULT AS IDENTITY,
    "case_no"             varchar(32) NOT NULL,
    "owner_id"            int8 DEFAULT NULL,
    "status"              varchar(20) NOT NULL DEFAULT 'DRAFT',
    "urgency_level"       varchar(16) NOT NULL DEFAULT 'NORMAL',
    "relation_type"       varchar(16) DEFAULT NULL,
    "name"                varchar(64) NOT NULL,
    "gender"              int2 NOT NULL DEFAULT 0,
    "birthday"            date DEFAULT NULL,
    "age_at_missing"      int4 DEFAULT NULL,
    "age_group"           varchar(16) DEFAULT NULL,
    "missing_time"        timestamp DEFAULT NULL,
    "province_code"       varchar(12) DEFAULT NULL,
    "city_code"           varchar(12) DEFAULT NULL,
    "district_code"       varchar(12) DEFAULT NULL,
    "address"             varchar(500) DEFAULT NULL,
    "hometown_code"       varchar(12) DEFAULT NULL,
    "lng"                 decimal(10, 6) DEFAULT NULL,
    "lat"                 decimal(10, 6) DEFAULT NULL,
    "height"              int4 DEFAULT NULL,
    "body_type"           varchar(16) DEFAULT NULL,
    "hair_type"           varchar(16) DEFAULT NULL,
    "accent"              varchar(100) DEFAULT NULL,
    "features"            varchar(500) DEFAULT NULL,
    "clothing"            varchar(255) DEFAULT NULL,
    "belongings"          varchar(255) DEFAULT NULL,
    "case_type"           varchar(20) NOT NULL DEFAULT 'MISSING',
    "narrative"           text DEFAULT NULL,
    "family_clues"        text DEFAULT NULL,
    "other_note"          varchar(1000) DEFAULT NULL,
    "police_reported"     bool DEFAULT NULL,
    "police_station"      varchar(100) DEFAULT NULL,
    "case_accepted_no"    varchar(64) DEFAULT NULL,
    "blood_sample_status" varchar(20) DEFAULT 'UNKNOWN',
    "follow_volunteer"    varchar(64) DEFAULT NULL,
    "contact_mode"        varchar(16) NOT NULL DEFAULT 'IN_APP',
    "contact_phone"       varchar(255) DEFAULT NULL,
    "found_time"          timestamp DEFAULT NULL,
    "found_confirm_type"  varchar(16) DEFAULT NULL,
    "found_remark"        varchar(500) DEFAULT NULL,
    "audit_remark"        varchar(500) DEFAULT NULL,
    "publish_time"        timestamp DEFAULT NULL,
    "last_confirm_time"   timestamp DEFAULT NULL,
    "archived_time"       timestamp DEFAULT NULL,
    "version"             int4 NOT NULL DEFAULT 0,
    "source_type"         varchar(16) NOT NULL DEFAULT 'APP',
    "source_code"         varchar(32) DEFAULT NULL,
    "source_id"           varchar(64) DEFAULT NULL,
    "source_url"          varchar(500) DEFAULT NULL,
    "fetch_time"          timestamp DEFAULT NULL,
    "dedupe_key"          varchar(64) DEFAULT NULL,
    "agreement_version"   varchar(16) DEFAULT NULL,
    "agreement_accepted"  bool NOT NULL DEFAULT false,
    "agreement_time"      timestamp DEFAULT NULL,
    "lead_count"          int4 NOT NULL DEFAULT 0,
    "view_count"          int4 NOT NULL DEFAULT 0,
    "favorite_count"      int4 NOT NULL DEFAULT 0,
    "report_count"        int4 NOT NULL DEFAULT 0,
    "create_user"         int8 DEFAULT NULL,
    "create_time"         timestamp NOT NULL,
    "update_user"         int8 DEFAULT NULL,
    "update_time"         timestamp DEFAULT NULL,
    "deleted"             int8 NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "gf_find_case_uk_case_no" ON "gf_find_case" ("case_no", "deleted");
CREATE UNIQUE INDEX IF NOT EXISTS "gf_find_case_uk_source" ON "gf_find_case" ("source_type", "source_code", "source_id", "deleted");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_status_urgency_missing_time" ON "gf_find_case" ("status", "urgency_level", "missing_time");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_status_publish_time" ON "gf_find_case" ("status", "publish_time");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_region" ON "gf_find_case" ("province_code", "city_code");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_owner" ON "gf_find_case" ("owner_id", "status");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_dedupe_key" ON "gf_find_case" ("dedupe_key");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_name" ON "gf_find_case" ("name");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_create_time" ON "gf_find_case" ("create_time");
CREATE INDEX IF NOT EXISTS "gf_find_case_idx_deleted" ON "gf_find_case" ("deleted");
COMMENT ON COLUMN "gf_find_case"."id" IS 'ID';
COMMENT ON COLUMN "gf_find_case"."case_no" IS '档案编号（对外展示）';
COMMENT ON COLUMN "gf_find_case"."owner_id" IS '发布人（App 用户 ID；采集来源为空）';
COMMENT ON COLUMN "gf_find_case"."status" IS '状态（DRAFT/PENDING_REVIEW/PUBLISHED/REJECTED/WITHDRAWN/FOUND/ARCHIVED/OFFLINE/BLOCKED/ERASED）';
COMMENT ON COLUMN "gf_find_case"."urgency_level" IS '紧急程度（NORMAL/URGENT/STANDING）';
COMMENT ON COLUMN "gf_find_case"."relation_type" IS '与本人关系（字典 relation_type）';
COMMENT ON COLUMN "gf_find_case"."name" IS '姓名';
COMMENT ON COLUMN "gf_find_case"."gender" IS '性别（0：未知；1：男；2：女）';
COMMENT ON COLUMN "gf_find_case"."birthday" IS '出生日期';
COMMENT ON COLUMN "gf_find_case"."age_at_missing" IS '失踪时年龄';
COMMENT ON COLUMN "gf_find_case"."age_group" IS '年龄段（字典 age_group）';
COMMENT ON COLUMN "gf_find_case"."missing_time" IS '失踪时间';
COMMENT ON COLUMN "gf_find_case"."province_code" IS '失踪省编码';
COMMENT ON COLUMN "gf_find_case"."city_code" IS '失踪市编码';
COMMENT ON COLUMN "gf_find_case"."district_code" IS '失踪区县编码';
COMMENT ON COLUMN "gf_find_case"."address" IS '详细地址（加密存储，仅完整视图返回）';
COMMENT ON COLUMN "gf_find_case"."hometown_code" IS '户籍地区划编码';
COMMENT ON COLUMN "gf_find_case"."lng" IS '经度（一期不采集，预留）';
COMMENT ON COLUMN "gf_find_case"."lat" IS '纬度（一期不采集，预留）';
COMMENT ON COLUMN "gf_find_case"."height" IS '失踪时身高（cm）';
COMMENT ON COLUMN "gf_find_case"."body_type" IS '体型';
COMMENT ON COLUMN "gf_find_case"."hair_type" IS '发型';
COMMENT ON COLUMN "gf_find_case"."accent" IS '口音';
COMMENT ON COLUMN "gf_find_case"."features" IS '疤痕/胎记等体貌特征';
COMMENT ON COLUMN "gf_find_case"."clothing" IS '失踪时衣着';
COMMENT ON COLUMN "gf_find_case"."belongings" IS '随身物品';
COMMENT ON COLUMN "gf_find_case"."case_type" IS '失踪情形（字典 case_type）';
COMMENT ON COLUMN "gf_find_case"."narrative" IS '发生经过';
COMMENT ON COLUMN "gf_find_case"."family_clues" IS '家庭背景及线索资料';
COMMENT ON COLUMN "gf_find_case"."other_note" IS '其他说明';
COMMENT ON COLUMN "gf_find_case"."police_reported" IS '是否已报警';
COMMENT ON COLUMN "gf_find_case"."police_station" IS '受理派出所';
COMMENT ON COLUMN "gf_find_case"."case_accepted_no" IS '警方立案编号';
COMMENT ON COLUMN "gf_find_case"."blood_sample_status" IS '血样采集情况（NOT_COLLECTED/COLLECTED/UNKNOWN）';
COMMENT ON COLUMN "gf_find_case"."follow_volunteer" IS '跟进志愿者';
COMMENT ON COLUMN "gf_find_case"."contact_mode" IS '联络方式（IN_APP/PHONE）';
COMMENT ON COLUMN "gf_find_case"."contact_phone" IS '可公开联系电话（加密存储）';
COMMENT ON COLUMN "gf_find_case"."found_time" IS '找回时间';
COMMENT ON COLUMN "gf_find_case"."found_confirm_type" IS '找回确认依据（POLICE/GUARDIAN/DNA）';
COMMENT ON COLUMN "gf_find_case"."found_remark" IS '找回说明';
COMMENT ON COLUMN "gf_find_case"."audit_remark" IS '最近一次审核意见';
COMMENT ON COLUMN "gf_find_case"."publish_time" IS '发布时间';
COMMENT ON COLUMN "gf_find_case"."last_confirm_time" IS '最后确认时间（时效计算基准）';
COMMENT ON COLUMN "gf_find_case"."archived_time" IS '归档时间';
COMMENT ON COLUMN "gf_find_case"."version" IS '当前版本号';
COMMENT ON COLUMN "gf_find_case"."source_type" IS '来源（APP/COLLECT/IMPORT）';
COMMENT ON COLUMN "gf_find_case"."source_code" IS '采集源标识';
COMMENT ON COLUMN "gf_find_case"."source_id" IS '采集源侧编号';
COMMENT ON COLUMN "gf_find_case"."source_url" IS '来源页面链接（可追溯）';
COMMENT ON COLUMN "gf_find_case"."fetch_time" IS '来源抓取时间';
COMMENT ON COLUMN "gf_find_case"."dedupe_key" IS '去重指纹';
COMMENT ON COLUMN "gf_find_case"."agreement_version" IS '合规告知版本号';
COMMENT ON COLUMN "gf_find_case"."agreement_accepted" IS '是否已勾选合规告知（真实承诺）';
COMMENT ON COLUMN "gf_find_case"."agreement_time" IS '合规告知确认时间';
COMMENT ON COLUMN "gf_find_case"."lead_count" IS '线索数（冗余）';
COMMENT ON COLUMN "gf_find_case"."view_count" IS '浏览数（冗余）';
COMMENT ON COLUMN "gf_find_case"."favorite_count" IS '收藏数（冗余）';
COMMENT ON COLUMN "gf_find_case"."report_count" IS '被举报次数（冗余）';
COMMENT ON COLUMN "gf_find_case"."create_user" IS '创建人';
COMMENT ON COLUMN "gf_find_case"."create_time" IS '创建时间';
COMMENT ON COLUMN "gf_find_case"."update_user" IS '修改人';
COMMENT ON COLUMN "gf_find_case"."update_time" IS '修改时间';
COMMENT ON COLUMN "gf_find_case"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON TABLE "gf_find_case" IS '寻人档案表';

CREATE TABLE IF NOT EXISTS "gf_find_case_media" (
    "id"          int8 GENERATED BY DEFAULT AS IDENTITY,
    "case_id"     int8 NOT NULL,
    "type"        varchar(16) NOT NULL DEFAULT 'PHOTO',
    "url"         varchar(500) NOT NULL,
    "thumb_url"   varchar(500) DEFAULT NULL,
    "storage_id"  int8 DEFAULT NULL,
    "sha256"      varchar(64) DEFAULT NULL,
    "sort"        int4 NOT NULL DEFAULT 0,
    "create_user" int8 DEFAULT NULL,
    "create_time" timestamp NOT NULL,
    "update_user" int8 DEFAULT NULL,
    "update_time" timestamp DEFAULT NULL,
    "deleted"     int8 NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "gf_find_case_media_idx_case_sort" ON "gf_find_case_media" ("case_id", "sort");
