COMMENT ON COLUMN "gf_find_case_media"."url" IS '地址';
COMMENT ON COLUMN "gf_find_case_media"."thumb_url" IS '缩略图地址';
COMMENT ON COLUMN "gf_find_case_media"."storage_id" IS 'sys_file ID';
COMMENT ON COLUMN "gf_find_case_media"."sha256" IS '内容摘要';
COMMENT ON COLUMN "gf_find_case_media"."sort" IS '排序';
COMMENT ON COLUMN "gf_find_case_media"."create_user" IS '创建人';
COMMENT ON COLUMN "gf_find_case_media"."create_time" IS '创建时间';
COMMENT ON COLUMN "gf_find_case_media"."update_user" IS '修改人';
COMMENT ON COLUMN "gf_find_case_media"."update_time" IS '修改时间';
COMMENT ON COLUMN "gf_find_case_media"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON TABLE "gf_find_case_media" IS '寻人档案媒体表';

