COMMENT ON COLUMN "gf_case_version"."operator_type" IS '操作人类型（APP/SYS）';
COMMENT ON COLUMN "gf_case_version"."create_user" IS '创建人';
COMMENT ON COLUMN "gf_case_version"."create_time" IS '创建时间';
COMMENT ON COLUMN "gf_case_version"."update_user" IS '修改人';
COMMENT ON COLUMN "gf_case_version"."update_time" IS '修改时间';
COMMENT ON COLUMN "gf_case_version"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON TABLE "gf_case_version" IS '寻人档案版本表';

CREATE TABLE IF NOT EXISTS "gf_case_status_log" (
    "id"            int8 GENERATED BY DEFAULT AS IDENTITY,
    "case_id"       int8 NOT NULL,
    "from_status"   varchar(20) DEFAULT NULL,
    "to_status"     varchar(20) NOT NULL,
    "reason_code"   varchar(32) DEFAULT NULL,
    "reason"        varchar(500) DEFAULT NULL,
    "operator_id"   int8 DEFAULT NULL,
    "operator_type" varchar(16) NOT NULL DEFAULT 'APP',
    "create_time"   timestamp NOT NULL,
    "create_user"   int8 DEFAULT NULL,
    "update_user"   int8 DEFAULT NULL,
    "update_time"   timestamp DEFAULT NULL,
    "deleted"       int8 NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "gf_case_status_log_idx_case_time" ON "gf_case_status_log" ("case_id", "create_time");
CREATE INDEX IF NOT EXISTS "gf_case_status_log_idx_deleted" ON "gf_case_status_log" ("deleted");
COMMENT ON COLUMN "gf_case_status_log"."id" IS 'ID';
