    "code"           varchar(32) NOT NULL,
    "name"           varchar(64) NOT NULL,
    "base_url"       varchar(255) NOT NULL,
    "list_path_tpl"  varchar(255) DEFAULT NULL,
    "detail_path_tpl" varchar(255) DEFAULT NULL,
    "category_ids"   varchar(255) DEFAULT NULL,
    "crawl_delay_ms" int4 DEFAULT 2000,
    "max_pages"      int4 NOT NULL DEFAULT 5,
    "request_timeout_ms" int4 DEFAULT 10000,
    "cron_expression" varchar(64) DEFAULT NULL,
    "enabled"        bool NOT NULL DEFAULT false,
    "authorization_note" varchar(500) DEFAULT NULL,
    "robots_allowed" bool NOT NULL DEFAULT false,
    "last_cursor"    varchar(255) DEFAULT NULL,
    "last_run_time"  timestamp DEFAULT NULL,
    "remark"         varchar(500) DEFAULT NULL,
    "create_user"    int8 DEFAULT NULL,
    "create_time"    timestamp NOT NULL,
    "update_user"    int8 DEFAULT NULL,
    "update_time"    timestamp DEFAULT NULL,
    "deleted"        int8 NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "gf_collect_source_uk_code" ON "gf_collect_source" ("code", "deleted");
CREATE INDEX IF NOT EXISTS "gf_collect_source_idx_deleted" ON "gf_collect_source" ("deleted");
COMMENT ON COLUMN "gf_collect_source"."id" IS 'ID';
COMMENT ON COLUMN "gf_collect_source"."code" IS '源标识';
COMMENT ON COLUMN "gf_collect_source"."name" IS '源名称';
COMMENT ON COLUMN "gf_collect_source"."base_url" IS '站点根地址';
COMMENT ON COLUMN "gf_collect_source"."list_path_tpl" IS '列表路径模板';
COMMENT ON COLUMN "gf_collect_source"."detail_path_tpl" IS '详情路径模板';
COMMENT ON COLUMN "gf_collect_source"."category_ids" IS '栏目/分类标识（JSON 数组）';
COMMENT ON COLUMN "gf_collect_source"."crawl_delay_ms" IS '同域抓取间隔（毫秒），不得低于站点声明值';
COMMENT ON COLUMN "gf_collect_source"."max_pages" IS '单轮最大列表页数';
COMMENT ON COLUMN "gf_collect_source"."request_timeout_ms" IS '请求超时（毫秒）';
COMMENT ON COLUMN "gf_collect_source"."cron_expression" IS '调度表达式';
COMMENT ON COLUMN "gf_collect_source"."enabled" IS '是否启用（默认关闭，须书面授权后开启）';
COMMENT ON COLUMN "gf_collect_source"."authorization_note" IS '授权依据说明';
COMMENT ON COLUMN "gf_collect_source"."robots_allowed" IS '最近一次 robots 判定结果';
COMMENT ON COLUMN "gf_collect_source"."last_cursor" IS '上次采集游标（页码等）';
COMMENT ON COLUMN "gf_collect_source"."last_run_time" IS '上次执行时间';
COMMENT ON COLUMN "gf_collect_source"."remark" IS '备注';
COMMENT ON COLUMN "gf_collect_source"."create_user" IS '创建人';
COMMENT ON COLUMN "gf_collect_source"."create_time" IS '创建时间';
COMMENT ON COLUMN "gf_collect_source"."update_user" IS '修改人';
COMMENT ON COLUMN "gf_collect_source"."update_time" IS '修改时间';
COMMENT ON COLUMN "gf_collect_source"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON TABLE "gf_collect_source" IS '采集源配置表';

